const isAlive = (liveNeighbors: number, wasAlive: boolean): boolean =>
  liveNeighbors === 3 || (liveNeighbors === 2 && wasAlive);

export function nextGeneration(cells: Cell[]): Cell[] {
  const livingKeys = new Set(cells.map(cellKey));

  // Every live cell adds one to each of its 8 neighbors, so tallying those
  // votes yields the candidate cells and their live-neighbor counts at once.
  const liveNeighborCounts = new Map<Cell, number>();
  const candidateByKey = new Map<string, Cell>();
  for (const cell of cells) {
    for (const neighbor of neighbors(cell)) {
      const key = cellKey(neighbor);
      const candidate = candidateByKey.get(key) ?? neighbor;
      candidateByKey.set(key, candidate);
      liveNeighborCounts.set(candidate, (liveNeighborCounts.get(candidate) ?? 0) + 1);
    }
  }

  return [...liveNeighborCounts]
    .filter(([cell, count]) => isAlive(count, livingKeys.has(cellKey(cell))))
    .map(([cell]) => cell);
}

